// Fork of "shortest rainbow / hue (93 ch)" https://shadertoy.com/view/ll2cDc
// more tricks: https://www.shadertoy.com/view/llySRh

   #define hue(v)  ( .6 + .6 * cos( 6.3*(v)  + vec4(0,23,21,0)  ) )
// #define hsv(c)  ( (c).z * ( 1. + (c).y* ( .6 * cos( 6.3*(c).x  + vec3(0,23,21)  ) -.4 ) ) ) 

void mainImage(out vec4 O, vec2 U) {
   U /= iResolution.xy;
   float n = ceil(exp2(1.+5.*U.y));    // number of slots in the palette
// float n = exp2(ceil(1.+5.*U.y));    // boring variant
   O = hue(floor(U.x*n)/n);            // spread the hue in the target amount of slots
}
